/// <summary>
/// <see cref="IRepository{T}"/> on the UM DbContext. The repository of each aggregate
/// root derives from it; override <see cref="WithDetails"/> to load more than the list
/// navigations.
/// </summary>
public abstract class EfRepository<T>(UMDbContext db) : IRepository<T> where T : AggregateRoot
{
    protected UMDbContext Db { get; } = db;

    /// <summary>The navigations loaded by <see cref="FindAsync"/>.</summary>
    protected virtual IQueryable<T> WithDetails(IQueryable<T> query) => query;

    public Task<T?> FindAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return WithDetails(Db.Set<T>()).FirstOrDefaultAsync(x => x.Id == id, cancellationToken);
    }

    public async Task<Page<T>> QueryAsync(PageRequest request, CancellationToken cancellationToken = default)
    {
        IQueryable<T> query = Db.Set<T>().AsNoTracking();
        var totalCount = await query.CountAsync(cancellationToken);
        query = request.OrderBy is null
            ? query.OrderBy(x => x.Id)
            : request.Descending
                ? query.OrderByDescending(x => EF.Property<object>(x, request.OrderBy))
                : query.OrderBy(x => EF.Property<object>(x, request.OrderBy));
        var items = await query
            .Skip((request.Page - 1) * request.PageSize)
            .Take(request.PageSize)
            .ToListAsync(cancellationToken);
        return new Page<T>(items, request.Page, request.PageSize, totalCount);
    }

    public void Add(T aggregate) => Db.Set<T>().Add(aggregate);

    public void Remove(T aggregate) => Db.Set<T>().Remove(aggregate);
}
using System.Text.Json;
using SolidOps.UM.Domain;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace SolidOps.UM.Infrastructure;

/// <summary>Mapping rules shared by every object of the UM module, applied by its DbContext.</summary>
public static class ModelConventions
{
    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

    /// <summary>
    /// A value object is stored as JSON in the row of its owner, nested value objects and
    /// collections included, and compared by value.
    /// </summary>
    public static PropertyBuilder<T> HasJsonConversion<T>(this PropertyBuilder<T> property)
    {
        property.HasConversion(
            value => JsonSerializer.Serialize(value, JsonOptions),
            json => JsonSerializer.Deserialize<T>(json, JsonOptions)!,
            new ValueComparer<T>(
                (left, right) => JsonSerializer.Serialize(left, JsonOptions) == JsonSerializer.Serialize(right, JsonOptions),
                value => JsonSerializer.Serialize(value, JsonOptions).GetHashCode(),
                value => JsonSerializer.Deserialize<T>(JsonSerializer.Serialize(value, JsonOptions), JsonOptions)!));
        return property;
    }

    /// <summary>
    /// An entity referencing an aggregate root is deleted with it; any other reference
    /// prevents the deletion of what it references (a conflict for the API).
    /// </summary>
    public static void ApplyDeleteRules(this ModelBuilder modelBuilder)
    {
        foreach (var foreignKey in modelBuilder.Model.GetEntityTypes().SelectMany(e => e.GetForeignKeys()))
        {
            var dependentIsEntity = !typeof(AggregateRoot).IsAssignableFrom(foreignKey.DeclaringEntityType.ClrType);
            var principalIsAggregate = typeof(AggregateRoot).IsAssignableFrom(foreignKey.PrincipalEntityType.ClrType);
            foreignKey.DeleteBehavior = dependentIsEntity && principalIsAggregate ? DeleteBehavior.Cascade : DeleteBehavior.Restrict;
        }
    }
}
