        var two = await PostAsync<TeamDto>("/teams", Team("two"));

        var response = await Client.PutAsJsonAsync($"/teams/{two.Id}", Team("two", Member("ada@example.com", true, one.Members[0].Id)));

        await AssertInvalidAsync(response, "Members[0].Id");
    }

    [TestMethod]
    public async Task UnknownTeamIsNotFound()
    {
        Assert.AreEqual(HttpStatusCode.NotFound, (await Client.GetAsync($"/teams/{UnknownId}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await Client.PutAsJsonAsync($"/teams/{UnknownId}", Team("t"))).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await Client.DeleteAsync($"/teams/{UnknownId}")).StatusCode);
    }

